"""
Alarms
"""
import csv
import json
import os
import re
from builtins import str
from taf.ul.trs_e2e_fw.lib.oam.admin.parameters import Parameters
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.exceptions import UnexpectedAlarmsFoundException, AlarmShouldNotExistException, \
    AlarmNotFoundException, AlarmNotFoundInRise, AlarmRiseValidationFailed, \
    AllAlarmOccurencesNotFoundException
from .mzoam_base import MzoamBaseClass


logger = BackgroundLogger.Instance()
ALARMS_DESCRIPTION_FILE = 'alarms_description.json'


class Alarms(MzoamBaseClass):
    """
    Alarms
    """
    def __init__(self):
        super(Alarms, self).__init__()

    def verify_alarm(self, **kwargs):
        """This function searches for alarm
        :param faultid: fault id of the alarm
        :param rat: supported values l|w|g. The RAT which the alarm belongs to.
        :param alarm_type: active | history
        :param severity: Alarm severity (critical, major, minor or warning)
        :param should_exist: Should the alarm exist or not
        :param occurrences: The number of instances expected for the alarm
        :param check_unexpected_alarms: Boolean to validate unexpected alarms or not
        :param expected_alarms: A list of faultids which will be ignored during validation
        :param prev_alarms: Alarms Json for validating against the current alarms
        :param timeout: Time to wait for positive procedure result
        :param alias: Name of execution context
        :raises: exception based on should_exist argument
        """

        faultid = kwargs.get("faultid", None)
        rat = kwargs.get("rat", "lte")
        alarm_type = kwargs.get("alarm_type", 'active')
        severity = kwargs.get("severity", None)
        should_exist = kwargs.get("should_exist", True)
        occurrences = kwargs.get("occurrences", 1)
        check_unexpected_alarms = kwargs.get("check_unexpected_alarms", False)
        expected_alarms = kwargs.get("expected_alarms", [])
        prev_alarms = kwargs.get("prev_alarms", None)

        if len(expected_alarms) > 0:
            expected_alarms = [int(x) for x in expected_alarms]

        timeout = kwargs.get("timeout", 300)
        alias = kwargs.get("alias", 'default')

        if faultid:
            faultid = int(faultid)
        # should_exist = bool(should_exist)
        if isinstance(should_exist, str):
            should_exist = should_exist.lower() in ('true', '1', 'yes', 'on')
        else:
            should_exist = bool(should_exist)
        occurrences = int(occurrences)
        timeout = int(timeout)
        if rat in get_config_variable(['rat_env']):
            return getattr(self, "_verify_in_{}_alarms".format(alarm_type.lower()))(
                faultid, severity, should_exist, occurrences, check_unexpected_alarms,
                expected_alarms, prev_alarms, timeout, alias)
        else:
            logger.info('Skipped verification for alarm {}, as it does not belong to'
                        'parent_rat {} not supported by this BTS'.format(faultid, rat))

    def _verify_in_active_alarms(self, faultid, severity, should_exist, occurrences,
                                 check_unexpected_alarms, expected_alarms, prev_alarms,
                                 timeout, alias):
        logger.debug("Getting active alarms....")
        alarm_object_list = self.mzom_client.get_active_alarms(timeout=timeout, session=alias)
        logger.debug(alarm_object_list)
        if severity is not None:
            alarm_object_list = [alarm_dict for alarm_dict in alarm_object_list if
                                 alarm_dict["perceivedSeverity"].lower().strip() ==
                                 severity.lower().strip()]
        logger.info('Alarms with given severity {}'.format(str(severity)))
        logger.info(alarm_object_list)
        self._write_alarms_to_file('active_alarms.json', alarm_object_list)
        self._verify_alarm_exists_and_validate_with_rise(alarm_object_list,
                                                         check_unexpected_alarms, prev_alarms,
                                                         expected_alarms, faultid, occurrences,
                                                         should_exist, alias)
        logger.info('alarms to be returned \n {}'.format(str(alarm_object_list)))
        return alarm_object_list

    def _verify_in_history_alarms(self, faultid, severity, should_exist, occurrences,
                                  check_unexpected_alarms, expected_alarms, prev_alarms,
                                  timeout, alias):
        logger.debug("Getting historical alarms....")
        alarm_object_list = self.mzom_client.get_historic_alarms(timeout=timeout, session=alias)
        logger.debug(alarm_object_list)
        if severity is not None:
            alarm_object_list = [alarm_dict for alarm_dict in alarm_object_list if
                                 alarm_dict["perceivedSeverity"].lower().strip() ==
                                 severity.lower().strip()]
        logger.info('Alarms with given severity {} \n {}'.format(str(severity),
                                                                 str(alarm_object_list)))
        self._write_alarms_to_file('history_alarms.json', alarm_object_list)
        self._verify_alarm_exists_and_validate_with_rise(alarm_object_list,
                                                         check_unexpected_alarms, prev_alarms,
                                                         expected_alarms, faultid,
                                                         occurrences, should_exist, alias)
        return alarm_object_list

    def _verify_alarm_exists_and_validate_with_rise(self, alarm_object_list,
                                                    check_unexpected_alarms, prev_alarms,
                                                    expected_alarms, faultid, occurrences,
                                                    should_exist, alias):
        unexpected_alarms = self._get_unexpected_alarms(alarm_object_list, prev_alarms, faultid,
                                                        expected_alarms)
        found_occurences = self._verify_alarm_exists(alarm_object_list, faultid)
        rise_alarm_found, rise_validation_pass = True, True
        # rise_alarm_found, rise_validation_pass = None, None
        # if faultid is not None and found_occurences > 0:
        # rise_alarm_found, rise_validation_pass = self._verify_alarm_against_rise(
        # alarm_object_list, faultid, alias)
        self._raise_exceptions(faultid, should_exist, found_occurences, occurrences,
                               rise_alarm_found, rise_validation_pass, check_unexpected_alarms,
                               unexpected_alarms)

    def _verify_alarm_exists(self, alarm_object_list, faultid):
        logger.debug("Verifying if alarms exist...")
        found_occurences = 0
        if faultid is not None:
            alarm_details = [alarm_obj for alarm_obj in alarm_object_list if
                             alarm_obj['specificProblem'] == int(faultid)]
            logger.debug("Alarm occurences :: {}".format(found_occurences))
            logger.debug("Alarms with given faultid :: \n{}".format(str(alarm_details)))
            found_occurences = len(alarm_details)
        return found_occurences

    def _get_unexpected_alarms(self, alarm_object_list, alarms_for_comparison, given_faultid,
                               expected_alarms):
        if expected_alarms is None:
            expected_alarms = []
        if given_faultid is not None:
            expected_alarms.append(int(given_faultid))

        if alarms_for_comparison:
            cur_fault_ids = [alarm['specificProblem'] for alarm in alarm_object_list if
                             alarm['specificProblem'] not in expected_alarms]
            logger.info('cur_fault_ids: {}'.format(cur_fault_ids))
            past_fault_ids = [alarm['specificProblem'] for alarm in alarms_for_comparison if
                              alarm['specificProblem'] not in expected_alarms]
            logger.info('past_fault_ids: {}'.format(past_fault_ids))
            unexpected_alarms = [f_id for f_id in cur_fault_ids if f_id not in past_fault_ids]
        else:
            unexpected_alarms = [alarm['specificProblem'] for alarm in alarm_object_list if
                                 alarm['specificProblem'] not in expected_alarms]
        return unexpected_alarms

    def _raise_exceptions(self, faultid, should_exist, found_occurences, req_occurrences,
                          rise_alarm_found, rise_validation_status, check_unexpected_alarms,
                          unexpected_alarms):
        if check_unexpected_alarms and len(unexpected_alarms) > 0:
            raise UnexpectedAlarmsFoundException('Alarms {}'.format(unexpected_alarms))
        logger.debug('faultid: {}, should_exist: {}, found_occurences: {}, req_occurrences: {}'
                     .format(faultid, should_exist, found_occurences, req_occurrences))
        logger.debug('rise_alarm_found: {}, rise_validation_status: {}, '
                     'check_unexpected_alarms: {}, '
                     'unexpected_alarms: {}'.format(rise_alarm_found,
                                                    rise_validation_status,
                                                    check_unexpected_alarms,
                                                    unexpected_alarms))
        if faultid is not None:
            if should_exist is False:
                if found_occurences > 0:
                    raise AlarmShouldNotExistException('Alarms {}'.format(faultid))
            else:
                if found_occurences == 0:
                    raise AlarmNotFoundException
                elif found_occurences >= req_occurrences:
                    if rise_alarm_found is False:
                        raise AlarmNotFoundInRise
                    else:
                        if rise_validation_status is False:
                            raise AlarmRiseValidationFailed
                        else:
                            logger.debug('Rise Validation Success')
                    if found_occurences > req_occurrences:
                        logger.debug('More Alarms {} found than expected {}'
                                     .format(found_occurences, req_occurrences))
                elif found_occurences < req_occurrences:
                    raise AllAlarmOccurencesNotFoundException('Expected: {}, Found: {}'
                                                              .format(req_occurrences,
                                                                      found_occurences))

    def _write_alarms_to_file(self, file_name, alarm_objects_list):
        alarms_file_name = 'execution_logs/{}'.format(file_name)
        if not os.path.exists(os.path.dirname(alarms_file_name)):
            os.makedirs(os.path.dirname(alarms_file_name))
        with open(alarms_file_name, 'a') as alarms_file:
            logger.debug("Writing alarms to {}".format(alarms_file_name))
            alarms_file.write('\n\n============================================================='
                              '=================\n\n')
            json.dump(alarm_objects_list, alarms_file)

    def _verify_alarm_against_rise(self, alarm_object_list, faultid, alias):
        rise_alarm_found = False
        rise_validation_pass = True
        rise_csv = get_config_variable(['rise_csv'])
        rise_header_fields = get_config_variable(['rise_header_fields'])
        for alarm_obj in alarm_object_list:
            alarm_faultid, alarm_faultname, alarm_id, alarm_name = \
                self._get_params_from_alarm_obj(alarm_obj)
            if int(faultid) == alarm_faultid:
                logger.info('given faultid: {}, foundid: {}'.format(faultid, alarm_faultid))
                rise_csv = get_resource_file(rise_csv)
                # rise_csv = os.path.join(self.config["config_path"], 'rise.csv')
                with open(rise_csv) as rise_fh:
                    reader = csv.DictReader(rise_fh, fieldnames=rise_header_fields)
                    for rise_row in reader:
                        alarm_rise_match = re.search(r'^-?\s*{}:\s*.*\n?'.format(alarm_faultid),
                                                     rise_row['Fault ID and name'])
                        if alarm_rise_match is not None:
                            logger.debug('Rise match found')
                            logger.debug('ADMIN alarm_faultid: {}'.format(alarm_faultid))
                            logger.debug('RISE faultid_and_name: {}'
                                         .format(rise_row['Fault ID and name']), '\n')
                            rise_alarm_found = True
                            rise_validation_pass = self._verify_alarmname_in_rise_reported_alarms(
                                alarm_id, alarm_name, rise_row, rise_validation_pass, alias)
                            rise_validation_pass = self._verify_faultname_in_rise(
                                alarm_faultname, rise_row, rise_validation_pass)
                            return rise_alarm_found, rise_validation_pass
        return rise_alarm_found, False

    def _verify_faultname_in_rise(self, alarm_faultname, rise_row, rise_validation_pass):
        rise_fault_name = rise_row['Fault name']
        logger.debug('ADMIN Fault_name: {}'.format(alarm_faultname))
        logger.debug('RISE fault_name: {}'.format(rise_fault_name), '\n')
        if '$' not in rise_fault_name:
            # If strings like $unit exist ignore this column
            if alarm_faultname.strip() != rise_fault_name.strip():
                logger.debug("Rise validation failed for faultName. \t\t\nADMIN:{}\t\t\nRISE:{}"
                             .format(alarm_faultname, rise_fault_name))
                rise_validation_pass = False
        return rise_validation_pass

    def _verify_alarmname_in_rise_reported_alarms(self, alarm_id, admin_alarm_name, rise_row,
                                                  rise_validation_pass, alias):
        rise_reported_alarms = rise_row['Reported alarms']
        rise_reported_alarms_desc = rise_row['Reported alarms description']
        logger.debug('ADMIN alarm_id: {}'.format(alarm_id))
        logger.debug('ADMIN alarm_name: {}'.format(admin_alarm_name))
        logger.debug('RISE Reported alarms: {}'.format(rise_reported_alarms), '\n')
        logger.debug('RISE Reported alarms desc: {}'.format(rise_reported_alarms_desc), '\n')

        rise_validation_pass = self._verify_rise_without_actcategoryalarms(
            admin_alarm_name, alarm_id, rise_reported_alarms, rise_validation_pass)
        return rise_validation_pass

    def _verify_rise_without_actcategoryalarms(self, admin_alarm_name, alarm_id,
                                               rise_reported_alarms, rise_validation_pass):
        if '$' not in rise_reported_alarms:
            rise_reported_alarms_matched = re.findall(r'.*?({}\s*{}).*?'.format(alarm_id,
                                                                                admin_alarm_name),
                                                      rise_reported_alarms, (re.DOTALL | re.I))
            if len(rise_reported_alarms_matched) == 0:
                rise_validation_pass = False
                logger.warn('ADMIN alarmname {} not found in RISE reported alarms'
                            .format(admin_alarm_name))
            return rise_validation_pass
        else:
            logger.info('Ignored reported alarms with $')

    def _verify_rise_actcategoryalarms_true(self, actCategoryAlarms, admin_alarm_name,
                                            rise_reported_alarms_for_false,
                                            rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_true) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE true category'
                        .format(actCategoryAlarms, admin_alarm_name))
        if len(rise_reported_alarms_for_false) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE false category'
                        .format(actCategoryAlarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE true category'
                    .format(actCategoryAlarms, admin_alarm_name))
        return rise_validation_pass

    def _verify_rise_actcategoryalarms_false(self, actCategoryAlarms, admin_alarm_name,
                                             rise_reported_alarms_for_false,
                                             rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_false) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE false category'
                        .format(actCategoryAlarms, admin_alarm_name))
        if len(rise_reported_alarms_for_true) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE true category'
                        .format(actCategoryAlarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE false category'
                    .format(actCategoryAlarms, admin_alarm_name))
        return rise_validation_pass

    def _get_params_from_alarm_obj(self, alarm_obj):
        alarm_fault = alarm_obj['additionaltext1']
        alarm_faultid = re.findall(r'(\d*)', alarm_fault)[0]
        alarm_id = alarm_obj['specificProblem']
        alarm_name = alarm_obj['alarmText']
        alarm_faultname = re.findall(r'[^0-9]+', alarm_fault)[0]
        return alarm_faultid, alarm_faultname, alarm_id, alarm_name
